        {"point": "Check the sender's email domain - company domains (@seabourn.com, @hagroup.com, @hollandamerica.com) indicate internal communications"},
        {"point": "Look for [EXTERNAL] tags in the subject line or external email warning banners in the body, which indicate external communications"},
        {"point": "Identify if the communication involves external vendors, agencies, or third-party service providers"},
        {"point": "Assess if the content relates to internal business processes or external services"},
        {"point": "Determine if the email is part of an internal workflow or requires specialized external handling"},
        {"point": "Check for non-company email domains (@gmail.com, @paralianshipping.com, etc.) which indicate external communications"},
        {"point": "Evaluate whether the conversation thread includes external participants"},
        {"point": "Note that emails requiring procurement, vendor management, or recruitment team handling are typically OUT_OF_SCOPE"}
      ],
      "confidence_score_assignment": {
        "positve_classication_score_guidelines": [
          {"point": "Assign 0.9-1.0 when the email is clearly internal communication between company employees using official domains"},
          {"point": "Assign 0.8-0.89 when most indicators point to internal communication with minor ambiguities"},
